  ('pulse', 'watch', 130, 'Vega Pulse', 'Your day, on your wrist.', 'The essential Vega watch — a bright always-on display, full health tracking, and multi-day battery in a light aluminium body.', 1799000, true, $vega${"bands":[{"name":"Midnight","bandA":"#2b2f3a","bandB":"#4a4f5e"},{"name":"Coral","bandA":"#ff8a5c","bandB":"#ffd9c0"},{"name":"Sky","bandA":"#6aa8ff","bandB":"#cfe2ff"}],"sizes":[{"label":"41mm","priceDelta":0},{"label":"45mm","priceDelta":500000}],"keySpecs":[{"icon":"display","label":"Display","value":"1.4\" AMOLED"},{"icon":"battery","label":"Battery","value":"3 days"},{"icon":"health","label":"Health","value":"HR + SpO₂"},{"icon":"water","label":"Water","value":"5 ATM"}],"pulse":{"bpm":72,"headline":"Your heart, checked around the clock.","body":"Vega Pulse reads your heart rate 24/7 and taps your wrist if it climbs too high or drops too low while you rest — with an on-demand blood-oxygen check whenever you want one."},"features":[{"icon":"sleep","title":"Sleep worth waking up to","body":"See your time in light, deep and REM each night, and a simple score that tells you how well you actually recovered."},{"icon":"safety","title":"Help is one tap away","body":"Hold the crown to call Emergency SOS and share your live location with your contacts — wherever you are."},{"icon":"everyday","title":"Your day, glanceable","body":"Calls, messages and reminders land on your wrist, so your phone can stay in your pocket."},{"icon":"battery","title":"Days, not hours","body":"Up to 3 days on a charge, and a quick morning top-up carries you through a full night of sleep tracking."}],"specGroups":[{"group":"Display","items":[{"label":"Type","value":"1.4\" AMOLED"},{"label":"Always-on","value":"Yes"},{"label":"Brightness","value":"1,000 nits"}]},{"group":"Health","items":[{"label":"Heart rate","value":"24/7"},{"label":"Blood oxygen","value":"SpO₂"},{"label":"Sleep","value":"Stages + score"}]},{"group":"Battery","items":[{"label":"Life","value":"Up to 3 days"},{"lab