  ('pulse-pro', 'watch', 140, 'Vega Pulse Pro', 'The pinnacle, on your wrist.', 'A titanium body, a brighter LTPO display, ECG and advanced sensors, and the longest battery in the line.', 3599000, true, $vega${"bands":[{"name":"Titanium","bandA":"#9aa0ab","bandB":"#d7dbe2"},{"name":"Graphite","bandA":"#3a3d45","bandB":"#5a5e68"},{"name":"Gold","bandA":"#e6c07a","bandB":"#f7e6c2"}],"sizes":[{"label":"45mm","priceDelta":0},{"label":"49mm","priceDelta":900000}],"keySpecs":[{"icon":"display","label":"Display","value":"1.5\" LTPO"},{"icon":"battery","label":"Battery","value":"5 days"},{"icon":"health","label":"Health","value":"ECG + HR"},{"icon":"water","label":"Water","value":"10 ATM"}],"pulse":{"bpm":68,"headline":"A clinic-grade read of your heart.","body":"Beyond 24/7 heart rate, Pulse Pro records an ECG right from your wrist in 30 seconds and flags irregular rhythms — the deepest heart insight Vega offers."},"features":[{"icon":"ecg","title":"Take an ECG anywhere","body":"Rest a finger on the crown for 30 seconds to record your heart's rhythm and check for signs of AFib."},{"icon":"sleep","title":"Sleep, fully understood","body":"Stages, a nightly score and overnight blood-oxygen trends, so a restless night never goes unexplained."},{"icon":"safety","title":"Safety, built in","body":"Fall detection, crash detection and Emergency SOS look out for you automatically, no tap required."},{"icon":"battery","title":"Five days of titanium","body":"The longest battery in the line, wrapped in a body milled from aerospace-grade titanium."}],"specGroups":[{"group":"Display","items":[{"label":"Type","value":"1.5\" LTPO AMOLED"},{"label":"Always-on","value":"Yes"},{"label":"Brightness","value":"2,000 nits"}]},{"group":"Health","items":[{"label":"Heart rate","value":"24/7"},{"label":"ECG","value":"Yes"},{"label":"Blood oxygen","value":"SpO₂"},{"label":"Sleep","value":"Stages + score"}]},{"group":"Battery","items":[{"label":"Life","value":"Up to 5 days"},{"label":"Charging","value"