  ('move', 'watch', 150, 'Vega Move', 'Built to go the distance.', 'The sport watch — dual-band GPS, a rugged reinforced body, and training metrics for every workout.', 2499000, true, $vega${"bands":[{"name":"Volt","bandA":"#b6e34d","bandB":"#e6f7b0"},{"name":"Coral","bandA":"#ff8a5c","bandB":"#ffd9c0"},{"name":"Slate","bandA":"#3a3d45","bandB":"#5a5e68"}],"sizes":[{"label":"43mm","priceDelta":0},{"label":"47mm","priceDelta":500000}],"keySpecs":[{"icon":"display","label":"Display","value":"1.4\" AMOLED"},{"icon":"battery","label":"Battery","value":"4 days"},{"icon":"health","label":"Health","value":"HR + SpO₂"},{"icon":"water","label":"Water","value":"5 ATM"}],"pulse":{"bpm":148,"headline":"Heart rate that keeps up with your run.","body":"A high-rate sensor tracks every zone as you push, so your effort — easy, threshold or all-out — is always honest, mile after mile."},"features":[{"icon":"gps","title":"Know every mile","body":"Dual-band GPS locks on fast and maps your route to the metre, even under tree cover or between tall buildings."},{"icon":"activity","title":"100+ ways to move","body":"From trail runs to open-water swims, pick your sport and Move tracks the metrics that matter for it."},{"icon":"recovery","title":"Train, then recover","body":"VO₂ max, training load and recovery time tell you when to go again — and when your body needs to rest."},{"icon":"water","title":"Rain, sweat or pool","body":"A reinforced body and 5 ATM water resistance shrug off whatever the workout throws at it."}],"specGroups":[{"group":"Display","items":[{"label":"Type","value":"1.4\" AMOLED"},{"label":"Always-on","value":"Yes"},{"label":"Brightness","value":"1,200 nits"}]},{"group":"Training","items":[{"label":"GPS","value":"Dual-band"},{"label":"Sport modes","value":"100+"},{"label":"Metrics","value":"VO₂ max, recovery"}]},{"group":"Battery","items":[{"label":"Life","value":"Up to 4 days"},{"label":"GPS battery","value":"Up to 30 hrs"}]},{"group":"Durability","items":[{"label":"Ca