  ('beam', 'audio', 160, 'Vega Beam', 'Everyday sound, untethered.', 'The essential Vega earbuds — custom 12mm drivers, a full day of battery with the case, and a snug, sweatproof fit.', 1099000, true, $vega${"shape":"buds","colors":[{"name":"Midnight","screenA":"#2b2f3a","screenB":"#4a4f5e"},{"name":"Coral","screenA":"#ff8a5c","screenB":"#ffd9c0"}],"keySpecs":[{"icon":"sound","label":"Drivers","value":"12mm dynamic"},{"icon":"battery","label":"Battery","value":"24h total"},{"icon":"mic","label":"Calls","value":"4 mics"},{"icon":"water","label":"Water","value":"IPX4"}],"sound":{"headline":"Big sound, small buds.","body":"Custom 12mm drivers push deep bass and clear highs, tuned by Vega so your everyday playlist feels a size bigger."},"features":[{"icon":"sound","title":"Signature Vega sound","body":"A tuned 12mm driver in each bud delivers warm bass and crisp detail, straight out of the case."},{"icon":"battery","title":"All-day battery","body":"6 hours in the buds and four more charges in the case — 24 hours before you reach for a cable."},{"icon":"charge","title":"Quick charge","body":"10 minutes in the case is good for 2 hours of listening when you're running out the door."},{"icon":"water","title":"Sweat and rain ready","body":"An IPX4 rating shrugs off workouts and weather, so they keep up wherever you go."}],"specGroups":[{"group":"Sound","items":[{"label":"Drivers","value":"12mm dynamic"},{"label":"Codecs","value":"AAC, SBC"}]},{"group":"Battery","items":[{"label":"Buds","value":"Up to 6 hrs"},{"label":"With case","value":"Up to 24 hrs"},{"label":"Quick charge","value":"10 min = 2 hrs"}]},{"group":"Fit & durability","items":[{"label":"Design","value":"In-ear, 3 tip sizes"},{"label":"Water resistance","value":"IPX4"}]}]}$vega$::jsonb),
