  ('aura', 'audio', 180, 'Vega Aura', 'Your studio, anywhere.', 'Over-ear headphones with immersive noise cancellation, 40mm drivers, spatial audio, and 40-hour battery in a plush, foldable body.', 2899000, true, $vega${"shape":"headphone","colors":[{"name":"Midnight","screenA":"#2b2f3a","screenB":"#4a4f5e"},{"name":"Silver","screenA":"#c9ced8","screenB":"#eef1f6"},{"name":"Sand","screenA":"#d9c3a3","screenB":"#f2e6d2"}],"keySpecs":[{"icon":"anc","label":"Noise","value":"Immersive ANC"},{"icon":"sound","label":"Drivers","value":"40mm"},{"icon":"battery","label":"Battery","value":"40h"},{"icon":"spatial","label":"Audio","value":"Spatial"}],"sound":{"headline":"Studio sound, all day.","body":"Custom 40mm drivers and immersive ANC wrap you in your music — and 40 hours of battery means the studio comes with you."},"features":[{"icon":"anc","title":"Immersive noise cancellation","body":"Eight microphones sense and silence the world around you, from engine drone to open-office chatter."},{"icon":"spatial","title":"Spatial audio with head tracking","body":"A cinema-like stage that stays anchored as you move, turning any seat into the best seat."},{"icon":"battery","title":"40-hour battery","body":"Two weeks of commutes on a charge, and a 5-minute top-up returns 5 hours when you're low."},{"icon":"fit","title":"Made to wear for hours","body":"Memory-foam cushions and a balanced headband stay comfortable long after the flight lands."}],"specGroups":[{"group":"Sound","items":[{"label":"Drivers","value":"40mm dynamic"},{"label":"Audio","value":"Hi-Res, spatial"},{"label":"Codecs","value":"LDAC, AAC, SBC"}]},{"group":"Noise control","items":[{"label":"ANC","value":"Immersive, adaptive"},{"label":"Transparency","value":"Yes"}]},{"group":"Battery","items":[{"label":"ANC on","value":"Up to 40 hrs"},{"label":"Quick charge","value":"5 min = 5 hrs"}]},{"group":"Comfort","items":[{"label":"Cushions","value":"Memory foam"},{"label":"Design","value":"Foldable, 250g"}]}]}$vega$::jsonb);
